<?php
require __DIR__.'/test_support.php';['db'=>$db,'fixture'=>$f]=erpTestFixture();
require __DIR__.'/../includes/marks_service.php';require __DIR__.'/../includes/auth.php';require __DIR__.'/../includes/exam_service.php';
$teacher=$f['ids']['teacher'];$class=$f['class'];$own=$f['subject'];$exam=$f['exam'];$student=$f['student'];
$db->prepare("INSERT INTO users(username,password,role,full_name,school_id,status) VALUES('class_teacher',?,'teacher','Synthetic Class Teacher',1,1)")->execute([password_hash('TestPassword123!',PASSWORD_DEFAULT)]);$ct=(int)$db->lastInsertId();
$db->prepare('UPDATE classes SET class_teacher_id=? WHERE id=?')->execute([$ct,$class]);
$other=(int)$db->query('SELECT subject_id FROM class_subjects WHERE class_id='.$class.' AND subject_id<>'.$own.' AND is_optional=0 LIMIT 1')->fetchColumn();
$db->prepare('INSERT INTO exam_subjects(exam_id,class_id,subject_id,theory_full,theory_pass,practical_full,practical_pass,credit_hours,is_optional) VALUES(?,?,?,75,26.25,25,10,4,0)')->execute([$exam,$class,$other]);
$scope=teacherClassResultScope($db,1,$ct,$class);erpEqual($scope['class_teacher'],true,'Class teacher without subject assignment gets class result authority');
erpEqual(teacherOwnsSubject($db,1,$ct,$class,$other),false,'Result authority does not grant curriculum ownership');
erpEqual(array_column(resultClasses($db,1,'teacher',$ct),'id'),[$class],'Only supervised class listed for an unassigned class teacher');
$parts=['theory'=>55,'participation'=>3,'project_work'=>12,'previous_exam'=>5];
$input=['exam_id'=>$exam,'class_id'=>$class,'marks'=>[$student=>[$other=>$parts]]];
erpReject(fn()=>saveExamMarks($db,1,$teacher,'teacher',$input),'Ordinary subject teacher cannot save other subject');
saveExamMarks($db,1,$ct,'teacher',$input);
erpEqual((int)$db->query('SELECT entered_by FROM marks WHERE subject_id='.$other)->fetchColumn(),$ct,'Class correction records its actual actor');
$parts['theory']=61;$input['marks'][$student]=[$own=>$parts,$other=>$parts];saveExamMarks($db,1,$ct,'teacher',$input);
erpEqual((int)$db->query('SELECT COUNT(*) FROM marks WHERE theory_obtained=61')->fetchColumn(),2,'Class teacher can save all configured subjects');
$db->prepare('UPDATE class_subjects SET section_id=? WHERE class_id=? AND subject_id=?')->execute([$f['section'],$class,$own]);
$db->prepare("INSERT INTO sections(class_id,name,school_id) VALUES(?,'B',1)")->execute([$class]);$sectionB=(int)$db->lastInsertId();
$db->prepare("INSERT INTO students(student_id,academic_year_id,class_id,section_id,first_name_en,gender,school_id,status) VALUES('SECOND-SECTION',1,?,?,'SectionB','Male',1,'active')")->execute([$class,$sectionB]);$studentB=(int)$db->lastInsertId();
$input['marks']=[$studentB=>[$own=>$parts,$other=>$parts]];saveExamMarks($db,1,$ct,'teacher',$input);
erpEqual((int)$db->query('SELECT COUNT(*) FROM marks WHERE student_id='.$studentB)->fetchColumn(),2,'Class teacher authority covers all class sections');
$snapshot=$db->query('SELECT * FROM marks ORDER BY id')->fetchAll();$input['marks']=[$studentB=>[$own=>$parts]];
erpReject(fn()=>saveExamMarks($db,1,$teacher,'teacher',$input),'Subject teacher cannot change another section');erpEqual($db->query('SELECT * FROM marks ORDER BY id')->fetchAll(),$snapshot,'Rejected section edit leaves marks unchanged');
changeExamState($db,1,$exam,'lock');erpReject(fn()=>saveExamMarks($db,1,$ct,'teacher',$input),'Class teacher cannot bypass exam lock');erpEqual($db->query('SELECT * FROM marks ORDER BY id')->fetchAll(),$snapshot,'Class teacher lock rejection preserves records');
changeExamState($db,1,$exam,'reopen');$input['marks']=[$student=>[$other=>$parts]];saveExamMarks($db,1,$ct,'teacher',$input);
$otherClass=(int)$db->query("SELECT id FROM classes WHERE school_id=1 AND name='Class 8'")->fetchColumn();
erpEqual(teacherClassResultScope($db,1,$ct,$otherClass)['class_teacher'],false,'Class supervision does not extend to another class');
Auth::startSession();$_SESSION=['user_id'=>$ct,'role'=>'teacher','school_id'=>1];
validateTeacherResultRequest($db,1,'results','ledger.php',[],['class'=>$otherClass]);erpCheck(true,'Unsupervised same-school ledger viewing is allowed');
erpReject(fn()=>validateTeacherResultRequest($db,1,'results','marks_entry.php',['class_id'=>$otherClass],[]),'Forged unsupervised marks form denied');
$_SESSION['user_id']=$teacher;
validateTeacherResultRequest($db,1,'results','ledger.php',[],['class'=>$class,'subject'=>$other]);erpCheck(true,'Unassigned subject ledger viewing is allowed');
erpEqual(count(resultClasses($db,1,'teacher',$ct,true)),(int)$db->query('SELECT COUNT(*) FROM classes WHERE school_id=1')->fetchColumn(),'Ledger class list includes all school classes');
$scope=teacherClassResultScope($db,1,$teacher,$class);erpEqual(teacherResultCellAllowed($scope,$own,$f['section']),true,'Assigned section visible');erpEqual(teacherResultCellAllowed($scope,$own,$sectionB),false,'Unassigned section not visible');
$db->exec('UPDATE users SET status=0 WHERE id='.$ct);erpReject(fn()=>saveExamMarks($db,1,$ct,'teacher',$input),'Inactive class teacher cannot change marks');
$db->exec('UPDATE users SET status=1 WHERE id='.$ct);$db->prepare('UPDATE classes SET class_teacher_id=? WHERE id=?')->execute([$teacher,$class]);erpReject(fn()=>saveExamMarks($db,1,$ct,'teacher',$input),'Reassigned class teacher loses authority immediately');
echo 'Teacher results passed: '.$GLOBALS['erp_checks']." checks\n";
